    fn start_election_timer(&self) {
        let this = self.clone();
        task::spawn(async move {
            loop {
                sleep(Raft::generate_election_timeout()).await;
                if let Err(error) = this.send_vote_request().await {
                    warn!("election initiation stopped: {}", error);
                    return;
                }
            }
        });
    }

    async fn send_vote_request(&self) -> Result<()> {
        let guard = self.storage_gate.lock().await;
        let (args, operation, context) = match self.inner.lock().unwrap().machine.begin_election() {
            Some(election) => election,
            None => return Ok(()),
        };
        let written = self.persist(operation).await?;
        let (net, peers, me, tally) = {
            let mut raft = self.inner.lock().unwrap();
            let reply = raft.machine.finish_rpc(context, written);
            if !matches!(reply, Some(RequestVoteReply { granted: true, .. }))
                || !raft.machine.campaign(args.term) { return Ok(()); }
            let mut tally = election::Tally::new(args, raft.peers.len()).expect("valid election membership");
            tally.record(raft.me, reply);
            raft.machine.elect(&tally);
            (raft.endpoint.clone(), raft.peers.clone(), raft.me, Arc::new(Mutex::new(tally)))
        };
        drop(guard);
        // Each real send uses the exact checked request authorized above.
        // Each RPC owns its request/peer context; all results reach the checked tally.
        // Checked collection, higher-term persistence and current-candidate promotion follow below.
        for (peer_id, peer) in peers.into_iter().enumerate() {
            if peer_id == me { continue; }
            let net = net.clone();
            let tally = tally.clone();
            let call = tally.lock().unwrap().outbound(peer_id).expect("valid peer");
            let this = self.clone();
            task::spawn(async move {
                let reply = net.call_timeout::<RequestVoteArgs>(peer, call.args(), Duration::from_millis(150)).await;
                let _gate = this.storage_gate.lock().await;
                let reply = reply.ok();
                let peer_id = call.destination();
                tally.lock().unwrap().complete_call(call, reply);
                if let Some(reply) = reply {
                    let term_write = this.inner.lock().unwrap().machine.prepare_term(peer_id, reply);
                    if let Some((operation, context)) = term_write {
                        match this.persist(operation).await {
                            Ok(written) => { if !this.inner.lock().unwrap().machine.finish_term(context, written) { return; } }
                            Err(error) => { warn!("term persistence failed: {}", error); return; }
                        }
                    }
                }
                this.inner.lock().unwrap().machine.elect(&tally.lock().unwrap());
            });
        }
        Ok(())
    }

